#!/usr/bin/env python3
"""OCR all 12 pages of huma3810.pdf using Tesseract."""
import subprocess
from pathlib import Path

BASE = Path("/Users/sinchunyeung/Desktop/ocr_huma3810")

# Page 1 is handwritten mixed-direction: use psm 4
# Pages 2-12 are mostly vertical traditional Chinese: use chi_tra_vert, psm 5
configs = []
for i in range(1, 13):
    if i == 1:
        cfg = {"lang": "chi_tra+eng", "psm": "4"}
    else:
        cfg = {"lang": "chi_tra_vert+eng", "psm": "5"}
    configs.append((i, cfg))

for i, cfg in configs:
    img = BASE / f"page_{i:02d}.png"
    out_prefix = BASE / f"page_{i:02d}_text"
    cmd = [
        "tesseract", str(img), str(out_prefix),
        "-l", cfg["lang"], "--psm", cfg["psm"]
    ]
    print(f"[Page {i}] tesseract ... {cfg}")
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print(f"  ERROR: {result.stderr.strip()}")
    else:
        print(f"  OK -> {out_prefix}.txt")
print("done")

