import json
with open('paddleocr_results.json', 'r', encoding='utf-8') as f:
    d = json.load(f)
# Check which pages have errors vs which have results
for i in range(1, 13):
    k = str(i)
    v = d.get(k)
    if v is None or v == []:
        print(f'Page {i}: empty/missing')
    elif isinstance(v, list) and len(v) > 0:
        pr = v[0]
        if isinstance(pr, dict):
            texts = pr.get('rec_texts', [])
            print(f'Page {i}: {len(texts)} regions')
        else:
            print(f'Page {i}: error or unexpected type: {type(pr)}')
    else:
        print(f'Page {i}: {v}')
